-- Inbound WhatsApp forward-in (#680, part 3 of #502): whatsapp_inbound_message (one provider message per workspace, the dedupe key) is a tenant table under FORCE RLS; the capture channel check gains 'whatsapp' (opt-in, like every channel but manual and upload); app_resolve_whatsapp_sender(e164) is the one workspace-free lookup, SECURITY DEFINER over an owner-only read policy on whatsapp_link, and returns a row only when exactly one verified link has the number (unknown and ambiguous are the same empty result). Expand only.
CREATE TABLE "whatsapp_inbound_message" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"provider_message_id" text NOT NULL,
	"media_id" text NOT NULL,
	"mime" text NOT NULL,
	"filename" text NOT NULL,
	"status" text DEFAULT 'received' NOT NULL,
	"received_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "whatsapp_inbound_message_workspace_provider_id_uq" UNIQUE("workspace_id","provider_message_id"),
	CONSTRAINT "whatsapp_inbound_message_status_chk" CHECK (status in ('received', 'stored', 'dropped'))
);
