CREATE FUNCTION app_resolve_whatsapp_sender(p_e164 text)
  RETURNS TABLE (workspace_id uuid, user_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT l.workspace_id, l.user_id FROM whatsapp_link l
    WHERE l.e164 = p_e164
      AND (SELECT count(*) FROM whatsapp_link x WHERE x.e164 = p_e164) = 1
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_resolve_whatsapp_sender(text) FROM PUBLIC;--> statement-breakpoint
